 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Complete monochrome rows/columns are panel separators.
    row_lines = [r for r in range(h) if len(set(grid[r])) == 1]
    col_lines = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(length, lines):
        cuts = [-1] + lines + [length]
        return [(cuts[i] + 1, cuts[i + 1]) for i in range(len(cuts) - 1)]

    row_segs = segments(h, row_lines)
    col_segs = segments(w, col_lines)
    # The most common non-separator value is the panel background.
    separators = {grid[r][0] for r in row_lines} | {grid[0][c] for c in col_lines}
    counts = Counter(v for row in grid for v in row if v not in separators)
    background = counts.most_common(1)[0][0]

    panels = []
    for r0, r1 in row_segs:
        for c0, c1 in col_segs:
            if r0 == r1 or c0 == c1:
                continue
            panel = [row[c0:c1] for row in grid[r0:r1]]
            score = sum(v != background for row in panel for v in row)
            panels.append((score, r0, r1, c0, c1, panel))
    _, _, _, _, _, source = max(panels, key=lambda x: x[0])
    out = [row[:] for row in grid]
    for _, r0, r1, c0, c1, _ in panels:
        for i in range(r1 - r0):
            for j in range(c1 - c0):
                out[r0 + i][c0 + j] = source[i][j]
    return out
